import{_ as a,o as s,c as e,a4 as t}from"./chunks/framework.B-wJupoK.js";const p="/assets/image-20260317122638100.CQqeKcEV.png",o="/assets/image-20260317122900073.DXYBFz8J.png",r="/assets/image-20260317122933642.BPmpjaTk.png",i="/assets/image-20260317123014337.BrARDOxk.png",l="/assets/image-20260317123110834.CqxCPM5s.png",g="/assets/image-20260317123542330.CLjTCSQI.png",c="/assets/image-20260317123622689.CNV2OLXs.png",m="/assets/image-20260317123700843.BWTB2emP.png",_="/assets/image-20260317123808600.D7o2YvDv.png",A=JSON.parse('{"title":"我的龙虾openclaw说要帮我跑15个小时来生成一部100w字的小说","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/我的龙虾openclaw说要帮我跑15个小时来生成一部100w字的小说/我的龙虾openclaw说要帮我跑15个小时来生成一部100w字的小说.md","filePath":"AI人工智能/我的龙虾openclaw说要帮我跑15个小时来生成一部100w字的小说/我的龙虾openclaw说要帮我跑15个小时来生成一部100w字的小说.md","lastUpdated":1773722708000,"__rawMarkdown":"# 我的龙虾openclaw说要帮我跑15个小时来生成一部100w字的小说\\n\\n## 前言\\n\\n当你有了一个24小时不睡觉的员工后，理论上你可以做任意之前你的电脑能做的事情了：\\n\\n1. 固化你的工作流程、盯盘、发帖、读邮件、写日报、处理财务报表等等\\n2. 也可以拿它去尝试做一些以前是人工长时间做的事情，比如这次的分享写小说。\\n\\n\\n\\n> 万少建立了一个专门讨论小龙虾**OpenClaw**的微信群，大家可以互相交流和分享关于小龙虾生态的资讯消息。\\n>\\n> 目前人已经超过200人了，私聊我进群。\\n\\n\\n\\n## 招聘一个新员工 “小说家”\\n\\n利用龙虾的多Agent能力，单独招聘一个新员工“小说家”\\n\\n![](assets/image-20260317122638100.png)\\n\\n---\\n\\n同时设定一些固有规则\\n\\n```\\n网文爽文型作家。擅长：快节奏叙事、爽点设计、黄金三章、打脸反转、金手指设定、角色塑造。风格：节奏紧凑、冲突密集、情绪到位、读者代入感强。工作目录：桌面的xiaoshuo文件夹，所有小说文件都必须存放在此目录下。\\n```\\n\\n## 开始写文章流程\\n\\n有了“小说家”的Agent之后，你要做什么事情，都要站在更高一个层次来使唤你的“小说家”员工即可：\\n\\n> 我想要编写一部长文本达100w字的小说，现在请你帮我制定一下编写方案，确保你和我都可以认可的这个小说的质量\\n\\n![image-20260317122900073](assets/image-20260317122900073.png)\\n\\n**小说家**帮我制定方案\\n\\n---\\n\\n![](assets/image-20260317122933642.png)\\n\\n---\\n\\n我做大老板，如果什么都要我思考，那还不如我去当这个**龙虾**！，所以我这样回应：\\n\\n> 请你现在帮我自主决定。我只需要保证最好你生成的是及格的、有特点的100w字的小说。然后你需要制定一个定时器，用来确保任务不会中断\\n\\n![](assets/image-20260317123014337.png)\\n\\n---\\n\\n**小说家**帮我设计一些方案\\n\\n![](assets/image-20260317123110834.png)\\n\\n---\\n\\n## 吝啬的老板\\n\\n我虽然开通了一些token的包月套餐，但是如果全部都拿来喂给这个**小说家**，那我这个**企业**的其他员工**口播家**、**摄影机**它们怎么办\\n\\n呢，考虑到这，我想了一个方案，喂给它稍微差一点的免费的智谱的token，让它专门用来的生成小说即可。\\n\\n\\n\\n\\n\\n## 最终\\n\\n经过一些交谈，目前我的小说家正在认真的生成小说，虽然它说要写10个小时，但是我既然提供了免费的、不是最好的粮食给他，\\n\\n那么等一等也就可以接受了。\\n\\n![](assets/image-20260317123542330.png)\\n\\n---\\n\\n![](assets/image-20260317123622689.png)\\n\\n---\\n\\n> **苏晚晴**就是我的小说的女主人公\\n\\n![](assets/image-20260317123700843.png)\\n\\n---\\n\\n我全局搜索了下 这个名字 **苏晚晴** ，看看故事是否连贯\\n\\n![](assets/image-20260317123808600.png)\\n\\n\\n\\n完美，连贯起来了。\\n\\n\\n\\n\\n\\n## 总结\\n\\n万少建立了一个专门讨论小龙虾**OpenClaw**的微信群，大家可以互相交流和分享关于小龙虾生态的资讯消息。\\n\\n目前人已经超过200人了，私聊我进群。\\n\\n**关注我**，持续分享鸿蒙开发 + AI 提效的实战技巧。\\n\\n\\n\\n![](https://blog.zbztb.cn/assets/%E5%BE%AE%E4%BF%A1%E5%8F%B7%E5%92%8C%E4%BA%8C%E7%BB%B4%E7%A0%81.KtucpRsB.jpg)"}'),h={name:"AI人工智能/我的龙虾openclaw说要帮我跑15个小时来生成一部100w字的小说/我的龙虾openclaw说要帮我跑15个小时来生成一部100w字的小说.md"};function d(u,n,b,w,k,q){return s(),e("div",null,[...n[0]||(n[0]=[t("",47)])])}const E=a(h,[["render",d]]);export{A as __pageData,E as default};
